  const numbers = values.map(Number)
  const isDragging = kind === "drag"
  const isLifted = kind === "lift"

  // At gesture start (and on settle) the shift exactly cancels the layout
  // change from the moved column leaving (or re-entering) the flow, both
  // landing in the same paint — easing the shift then would make the whole
  // board lurch on pickup, so net-zero poses apply instantly.
  const columnDragState = board.columnDrag.get()
  const shiftIsInstant =
    columnDragState === null ||
    (columnDragState.over !== null &&
      columnDragState.over.index === columnDragState.fromIndex &&
      columnDragState.deltaX === 0)

  return (
    <KanbanColumnContext.Provider value={contextValue}>
      <div
        role="group"
        {...props}
        ref={composedRef}
        data-slot="kanban-column"
        data-column-id={columnId}
        data-dragging={isDragging ? "true" : undefined}
        data-lifted={isLifted ? "true" : undefined}
        className={cn(
          "box-border flex flex-col",
          // A lifted column leaves the flow exactly as a dragged one does,
          // so the sibling math is identical for both input modes.
          "data-[dragging=true]:fixed data-[dragging=true]:z-50 data-[dragging=true]:cursor-grabbing data-[dragging=true]:shadow-xl",
          "data-[lifted=true]:fixed data-[lifted=true]:z-50 data-[lifted=true]:shadow-xl",
          "transition-transform [transition-duration:var(--nessa-kanban-motion-duration,var(--nessa-motion-duration-fast))] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
          className,
        )}
        style={
          {
            ...style,
            ...(isDragging || isLifted
              ? {
                  left: numbers[2],
                  top: numbers[3],
                  width: numbers[4],
                  height: numbers[5],
                  "--nessa-kanban-motion-duration": "0s",
                  transform: `translate3d(${numbers[0]}px, ${numbers[1]}px, 0)`,
                }
              : null),
            ...(kind === "shift"
              ? { transform: `translate3d(${numbers[0]}px, 0, 0)` }
              : null),
            // Only the kit's own duration is zeroed — `transition: none`
            // would also kill the consumer's, on every idle render.
            ...(shiftIsInstant && !isDragging
              ? { "--nessa-kanban-motion-duration": "0s" }
              : null),
          } as React.CSSProperties
        }
      />
    </KanbanColumnContext.Provider>
  )
}

/** Properties accepted by the column drag handle. */
interface KanbanColumnHandleProps extends React.ComponentProps<"button"> {}

/**
 * The grip that moves a whole column. Place it in the column's header;
 * dragging it slides the column while its siblings part to show where it
 * will land, and releasing reports the new position through the board's
 * `onColumnMove`. It is keyboard-operable the same way cards are: Space or
 * Enter lifts the column, the left and right arrows walk it between
 * positions, Space drops it, and Escape cancels.
 *
 * @param props - Native button properties; children replace the default
 * grip glyph.
 * @returns The handle button element.
 */
function KanbanColumnHandle({
  className,
  children,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onKeyDown,
  onBlur,
  onClick,
  ...props
}: KanbanColumnHandleProps) {
  const board = useKanban("KanbanColumnHandle")
  const column = React.useContext(KanbanColumnContext)

  if (column === null) {
    throw new Error("KanbanColumnHandle must be used within a KanbanColumn.")
  }

  const { columnId } = column
  // A drag ends with a trailing click on this button; it belongs to the
  // gesture, not to whatever the consumer wired to the handle.
  const suppressClickRef = React.useRef(false)
  const pointerRef = React.useRef<{
    pointerId: number
    startClientX: number
    startClientY: number
    started: boolean
  } | null>(null)

  const isLifted = React.useSyncExternalStore(
    board.columnDrag.subscribe,
    () => {
      const state = board.columnDrag.get()

      return state?.columnId === columnId && state.mode === "keyboard"
    },
    () => false,
  )

  return (
    <button
      type="button"
      aria-label="Move column"
      aria-pressed={isLifted}
      {...props}
      data-slot="kanban-column-handle"
      className={cn(
        "box-border inline-flex cursor-grab appearance-none items-center justify-center rounded-md border-0 bg-transparent p-0 text-muted-foreground hover:text-foreground",
        "touch-none aria-pressed:cursor-grabbing",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        className,
      )}
      onPointerDown={(event) => {
        onPointerDown?.(event)

        if (
          event.defaultPrevented ||
          event.button !== 0 ||
          pointerRef.current
        ) {
          return
        }

        // Reaching for the pointer abandons a keyboard lift rather than
        // leaving it stranded — pressing the handle is a clear change of
        // intent, and the press then arms normally. A gesture a pointer
        // already owns keeps the board, so this press stays inert until it
        // settles. Without this the press arms, the begin is refused at
        // the threshold, and every retry is swallowed while still
        // delivering a click to the consumer.
        const inFlightColumn = board.columnDrag.get()
        const inFlightCard = board.drag.get()

        if (inFlightColumn !== null) {
          if (inFlightColumn.mode === "keyboard") {
            board.cancelColumnDrag()
          } else {
            return
          }
        } else if (inFlightCard !== null) {
          if (inFlightCard.mode === "keyboard") {
            board.cancelDrag()
          } else {
            return
          }
        }

        try {
          event.currentTarget.setPointerCapture(event.pointerId)
        } catch {
          // Synthetic pointer events (tests) have no capturable pointer id;
          // moving still works through the element's own move events.
        }

        suppressClickRef.current = false
        pointerRef.current = {
          pointerId: event.pointerId,
          startClientX: event.clientX,
          startClientY: event.clientY,
          started: false,
        }
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event)

        const pointer = pointerRef.current

        if (!pointer || pointer.pointerId !== event.pointerId) {
          return
        }

        if (!pointer.started) {
          if (Math.abs(event.clientX - pointer.startClientX) < 3) {
            return
          }

          const root = event.currentTarget.closest<HTMLElement>(
            '[data-slot="kanban-column"]',
          )
          const rect = root?.getBoundingClientRect()

          if (
            !root ||
            !rect ||
            !board.beginColumnDrag(columnId, event.clientX, {
              left: rect.left,
              top: rect.top,
              width: root.offsetWidth,
              height: root.offsetHeight,
            })
          ) {
            pointerRef.current = null

            if (event.currentTarget.hasPointerCapture(event.pointerId)) {
              event.currentTarget.releasePointerCapture(event.pointerId)
            }

            return
          }

          pointer.started = true
          suppressClickRef.current = true

          // Safari and Firefox do not focus a pressed button, and the
          // Escape-cancels-drag path needs the key to land here.
          event.currentTarget.focus({ preventScroll: true })

          // The begin commit renders the pure net-zero pose so sibling
          // shifts apply without easing; the float catches up next move.
          return
        }

        board.moveColumnDrag(
          columnId,
          pointer.startClientX,
          pointer.startClientY,
          event.clientX,
          event.clientY,
        )
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event)

        const pointer = pointerRef.current

        if (!pointer || pointer.pointerId !== event.pointerId) {
          return
        }

        pointerRef.current = null

        if (event.currentTarget.hasPointerCapture(event.pointerId)) {
          event.currentTarget.releasePointerCapture(event.pointerId)
        }

        if (pointer.started) {
          // The threshold-crossing move deliberately renders the net-zero
          // pickup pose without travelling, so a gesture whose whole
          // journey arrived in that one event would otherwise settle back
          // at its origin. The release position always has the final say;
          // both updates batch into this handler, so nothing paints in
          // between — exactly as a card drag settles.
          board.moveColumnDrag(
            columnId,
            pointer.startClientX,
            pointer.startClientY,
            event.clientX,
            event.clientY,
          )
          board.endColumnDrag(columnId)
        }
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)

        if (pointerRef.current?.pointerId !== event.pointerId) {
          return
        }

        const started = pointerRef.current.started

        pointerRef.current = null

        // Only this handle's own gesture is abandoned — a press that never
        // became a drag must not cancel someone else's.
        if (started && board.columnDrag.get()?.columnId === columnId) {
          board.cancelColumnDrag()
        }
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event)

        if (event.defaultPrevented) {
          return
        }

        // Escape abandons a pointer drag the same way it abandons a lift —
        // the press focused the handle, so the key lands here.
        if (pointerRef.current?.started && event.key === "Escape") {
          event.preventDefault()
          pointerRef.current = null

          if (board.columnDrag.get()?.columnId === columnId) {
            board.cancelColumnDrag()
          }

          return
        }

        if (event.key === " " || event.key === "Enter") {
          // Held keys still scroll nothing, but only the first press
          // acts: auto-repeat would otherwise toggle lift and drop tens
          // of times a second, flooding the live region.
          event.preventDefault()

          if (event.repeat) {
            return
          }

          if (isLifted) {
            board.dropColumnLift()
          } else {
            board.liftColumn(columnId)
          }

          return
        }

        if (!isLifted) {
          return
        }

        if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
          event.preventDefault()
          board.moveColumnLift(event.key === "ArrowLeft" ? "left" : "right")
        } else if (event.key === "Escape") {
          event.preventDefault()
          board.cancelColumnDrag()
        }
      }}
      onClick={(event) => {
        // Only a pointer-trailing click (detail >= 1) can conclude a drag;
        // a keyboard activation arrives with detail 0 and must never be
        // eaten by suppression a click-less touch drag left armed.
        if (suppressClickRef.current && event.detail !== 0) {
          suppressClickRef.current = false
          event.preventDefault()
          event.stopPropagation()
          return
        }

        onClick?.(event)
      }}
      onBlur={(event) => {
        onBlur?.(event)

        // A lifted column whose focus walks away settles back where it
        // was, rather than leaving the board stuck mid-move.
        if (isLifted) {
          board.cancelColumnDrag()
        }
      }}
    >
      {children ?? (
        <svg aria-hidden="true" viewBox="0 0 10 10" className="size-3.5">
          <path
            d="M3 2.5h.01M3 5h.01M3 7.5h.01M7 2.5h.01M7 5h.01M7 7.5h.01"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
          />
        </svg>
      )}
    </button>
  )
}

/** Properties accepted by a column's card list. */
interface KanbanColumnListProps extends React.ComponentProps<"div"> {
  /**
   * Whether this column takes cards dropped into it. A closed column is
   * skipped when resolving drop targets and when a keyboard move walks
   * between columns — the way a WIP limit or a locked stage behaves.
   * @defaultValue true
   */
  accepts?: boolean
}

/**
 * The drop area of a column: the region cards live in, drags measure
 * against, and the drop indicator draws inside. Compose the column's
 * `KanbanCard` children here. The list keeps a minimum height so an empty
 * column still accepts drops.
 *
 * @param props - Native container properties; children are the cards.
 * @returns The registered list element.
 */
function KanbanColumnList({
  accepts = true,
  className,
  children,
  ref,
  ...props
}: KanbanColumnListProps) {
  const board = useKanban("KanbanColumnList")
  const column = React.useContext(KanbanColumnContext)

  if (column === null) {
    throw new Error("KanbanColumnList must be used within a KanbanColumn.")
  }

  const { columnId } = column
  const elementRef = React.useRef<HTMLDivElement>(null)
  const composedRef = React.useMemo(
    () => composeKanbanRefs(elementRef, ref),
    [ref],
  )

  React.useLayoutEffect(() => {
    const element = elementRef.current

    if (!element) {
      return
    }

    return board.registerColumn(columnId, element, accepts)
  }, [accepts, board, columnId])

  // The snapshot collapses to this column's opened slot (or null), so
  // drags over other columns never re-render this list. The two numbers
  // are packed into one string so the snapshot stays reference-stable
  // between identical reads.
  const slot = React.useSyncExternalStore(
    board.drag.subscribe,
    () => {
      const state = board.drag.get()

      return state?.over && state.over.columnId === columnId
        ? `${state.over.gapTop}:${state.over.gapHeight}:${state.over.spacing}`
        : null
    },
    () => null,
  )
  const [gapTop, gapHeight, gapSpacing] = slot
    ? slot.split(":").map(Number)
    : [null, null, null]

  return (
    <div
      role="list"
      {...props}
      ref={composedRef}
      data-slot="kanban-column-list"
      data-accepts={accepts ? undefined : "false"}
      data-drop-target={gapTop !== null ? "true" : undefined}
      className={cn(
        "relative box-border flex min-h-10 flex-col gap-2",
        className,
      )}
      // The cards part with transforms, which open the slot without
      // growing the list. Reserving the slot's height as padding lets the
      // column stretch to its dropped size — and padding, unlike a real
      // element, leaves every card's measured offset untouched, so the
      // insertion index can never chase its own preview.
      style={
        gapHeight !== null
          ? { ...props.style, paddingBottom: gapHeight }
          : props.style
      }
    >
      {children}
      {gapTop !== null && gapHeight !== null ? (
        // The cards have parted to leave exactly this space; the outline
        // fills it so the drop reads as a preview of the resting place.
        <span
          aria-hidden="true"
          data-slot="kanban-drop-indicator"
          className="pointer-events-none absolute inset-x-0 rounded-xl border-2 border-dashed border-ring/50 bg-ring/5"
          // The column's own measured gap is subtracted, not a literal:
          // the slot is card + spacing, and the outline previews the card.
          style={{
            top: gapTop,
            height: Math.max(gapHeight - (gapSpacing ?? 0), 0),
          }}
        />
      ) : null}
    </div>
  )
}

export {
  KanbanColumn,
  KanbanColumnHandle,
  KanbanColumnList,
  type KanbanColumnHandleProps,
  type KanbanColumnListProps,
  type KanbanColumnProps,
}

"use client"

/** @responsibility Renders one draggable kanban card, owning its pointer drag gesture and the keyboard lift-move-drop flow. */

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  KanbanColumnContext,
  composeKanbanRefs,
  useKanban,
} from "./kanban-context"

/** State snapshotted for the lifetime of one card pointer gesture. */
interface KanbanCardPointerState {
  /** The pointer that started the gesture; other pointers are ignored. */
  pointerId: number
  startClientX: number
  startClientY: number
  /** Whether the pointer travelled far enough to count as a drag. */
  started: boolean
}

/** Properties accepted by one kanban card. */
interface KanbanCardProps extends React.ComponentProps<"div"> {
  /** The card's unique id within its board, referenced by moves. */
  cardId: string
  /**
   * Whether this card is pinned in place: it still takes focus and still
   * holds a slot other cards move around, but it cannot itself be picked
   * up by pointer or keyboard.
   * @defaultValue false
   */
  disabled?: boolean
}

/**
 * Reads whether a pointer-down landed on something that owns its own
 * gesture — a control, editable text, or anything marked
 * `data-kanban-no-drag` — so dragging never steals from it.
 *
 * @param target - The event target.
 * @returns Whether the card should leave the gesture alone.
 */
function targetOwnsGesture(target: Element): boolean {
  return (
    target.closest(
      'button, a, input, textarea, select, [contenteditable="true"], [data-kanban-no-drag]',
    ) !== null
  )
}

/**
 * One card on a kanban board: a focusable container rendering any content.
 * It drags with the pointer — floating from its spot while the drop
 * indicator marks where it will land — and moves with the keyboard: Space
 * or Enter lifts the focused card, the arrow keys walk it through
 * positions and columns, Space drops it, and Escape cancels. Label it with
 * `aria-label`; announcements read it. Controls inside the card, and
 * anything marked `data-kanban-no-drag`, never start a drag.
 *
 * @param props - The card id and native container properties.
 * @returns The card element.
 */
function KanbanCard({
  cardId,
  disabled = false,
  className,
  style,
  ref,
  onPointerDown,
  onPointerMove,
  onPointerUp,
  onPointerCancel,
  onKeyDown,
  onClick,
  onBlur,
  ...props
}: KanbanCardProps) {
  const board = useKanban("KanbanCard")
  const column = React.useContext(KanbanColumnContext)

  if (column === null) {
    throw new Error("KanbanCard must be used within a KanbanColumn.")
  }

  const { columnId } = column
  const elementRef = React.useRef<HTMLDivElement>(null)
  const composedRef = React.useMemo(
    () => composeKanbanRefs(elementRef, ref),
    [ref],
  )
  const pointerStateRef = React.useRef<KanbanCardPointerState | null>(null)
  const suppressClickRef = React.useRef(false)

  React.useLayoutEffect(() => {
    const element = elementRef.current

    if (!element) {
      return
    }

    return board.registerCard(cardId, columnId, element)
  }, [board, cardId, columnId])

  // The snapshot is this card's own drag state or a stable null, so drags
  // of other cards never re-render this one.
  const dragState = React.useSyncExternalStore(
    board.drag.subscribe,
    () => {
      const state = board.drag.get()

      return state && state.cardId === cardId ? state : null
    },
    () => null,
  )

  const isPointerDragging = dragState?.mode === "pointer"
  const isLifted = dragState?.mode === "keyboard"

  // How far this card slides to open the slot for the card being moved.
  // The snapshot is a plain number, so cards that are not moving never
  // re-render as the drag travels.
  const shift = React.useSyncExternalStore(
    board.drag.subscribe,
    () => {
      const state = board.drag.get()

      return state?.over?.shiftedCardIds.has(cardId) ? state.over.gapHeight : 0
    },
    () => 0,
  )

  // A drag beginning (or settling) puts the board in a net-zero pose: the
  // moved card leaves (or re-enters) the flow and this shift exactly
  // cancels the layout change, both landing in the same paint. Easing the
  // shift then would make every card dip and slide back — the whole board
  // appearing to move on a mere pickup — so in those poses it applies
  // instantly, and only genuine re-targeting mid-drag animates.
  const wholeDrag = board.drag.get()
  const shiftIsInstant =
    wholeDrag === null ||
    (wholeDrag.over !== null &&
      wholeDrag.over.columnId === wholeDrag.fromColumn &&
      wholeDrag.over.index === wholeDrag.fromIndex &&
      wholeDrag.deltaX === 0 &&
      wholeDrag.deltaY === 0)

  const handlePointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(event)

    // A touch drag ends without a trailing click, so any suppression left
    // armed from a previous gesture retires when a new one begins.
    suppressClickRef.current = false

    if (
      event.defaultPrevented ||
      disabled ||
      board.readOnly ||
      event.button !== 0 ||
      pointerStateRef.current ||
      targetOwnsGesture(event.target as Element)
    ) {
      return
    }

    const inFlight = board.drag.get()

    if (inFlight !== null) {
      // Reaching for the pointer abandons a keyboard lift rather than
      // leaving it stranded — pressing a card is a clear change of intent,
      // and the press then arms normally. A pointer drag already owns the
      // board, so this press stays inert until it settles.
      if (inFlight.mode === "keyboard") {
        board.cancelDrag()
      } else {
        return
      }
    }

    try {
      event.currentTarget.setPointerCapture(event.pointerId)
    } catch {
      // Synthetic pointer events (tests) have no capturable pointer id;
      // dragging still works through the element's own move events.
    }

    pointerStateRef.current = {
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      started: false,
    }
  }

  const handlePointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    onPointerMove?.(event)

    const pointerState = pointerStateRef.current

    if (!pointerState || pointerState.pointerId !== event.pointerId) {
      return
    }

    if (!pointerState.started) {
      // A tiny wobble under the pointer stays a click, not a drag.
      if (
        Math.hypot(
          event.clientX - pointerState.startClientX,
          event.clientY - pointerState.startClientY,
        ) < 3
      ) {
        return
      }

      // The board may refuse — another pointer or a keyboard lift already
      // owns it — and a refused gesture disarms itself for good.
      const rect = event.currentTarget.getBoundingClientRect()

      if (
        !board.beginPointerDrag(cardId, columnId, event.clientX, event.clientY, {
          left: rect.left,
          top: rect.top,
          width: event.currentTarget.offsetWidth,
          height: event.currentTarget.offsetHeight,
        })
      ) {
        pointerStateRef.current = null

        if (event.currentTarget.hasPointerCapture(event.pointerId)) {
          event.currentTarget.releasePointerCapture(event.pointerId)
        }

        return
      }

      pointerState.started = true

      // Chrome focuses a pressed tabindex element, Safari and Firefox do
      // not — and the Escape-cancels-drag path needs the key to land
      // here, so the drag takes focus explicitly.
      event.currentTarget.focus({ preventScroll: true })

      // This event's few pixels are not applied: the begin commit must
      // render the pure net-zero pose (delta 0, slot at origin) so the
      // compensating shifts apply without easing — otherwise every other
      // card visibly dips on a mere pickup. The float catches up on the
      // very next move.
      return
    }

    board.movePointerDrag(
      cardId,
      pointerState.startClientX,
      pointerState.startClientY,
      event.clientX,
      event.clientY,
    )
  }

  const handlePointerEnd = (
    event: React.PointerEvent<HTMLDivElement>,
    cancelled: boolean,
  ) => {
    const pointerState = pointerStateRef.current

    if (!pointerState || pointerState.pointerId !== event.pointerId) {
      return
    }

    pointerStateRef.current = null

    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId)
    }

    if (!pointerState.started) {
      return
    }

    if (cancelled) {
      // A cancelled gesture produces no trailing click; arming the
      // suppression here would swallow the next genuine click instead.
      // Only this card's own drag is cancelled — never someone else's.
      if (board.drag.get()?.cardId === cardId) {
        board.cancelDrag()
      }
    } else {
      suppressClickRef.current = true
      // The threshold-crossing move deliberately renders the net-zero
      // pose without travelling, so a gesture whose whole journey arrived
      // in that one event would otherwise settle back at its origin. The
      // release position always has the final say; both updates batch into
      // this handler, so nothing paints in between.
      board.movePointerDrag(
        cardId,
        pointerState.startClientX,
        pointerState.startClientY,
        event.clientX,
        event.clientY,
      )
      board.endPointerDrag(cardId)
    }
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event)

    // Movement keys act on the card itself, never on a focused control
    // inside it.
    if (event.defaultPrevented || event.target !== event.currentTarget) {
      return
    }

    if (event.key === " " || event.key === "Enter") {
      // A lift already in flight always settles, even if the card turned
      // disabled underneath it: refusing the drop would strand the card
      // in a state the arrow keys can still move but nothing can end.
      if (isLifted) {
        // Held keys still scroll nothing, but only the first press acts:
        // auto-repeat would otherwise toggle lift and drop tens of times
        // a second, flooding the live region.
        event.preventDefault()

        if (!event.repeat) {
          board.dropLift()
        }

        return
      }

      if (disabled || board.readOnly) {
        return
      }

      event.preventDefault()

      if (!event.repeat && board.drag.get() === null) {
        board.liftCard(cardId, columnId)
      }

      return
    }

    // Escape abandons a pointer drag the same way it abandons a lift —
    // the press focused the card, so the key lands here.
    if (isPointerDragging && event.key === "Escape") {
      event.preventDefault()
      pointerStateRef.current = null
      // The mouse button is still down; its eventual release fires a
      // trailing click that belongs to the abandoned drag, not to the card.
      suppressClickRef.current = true
      board.cancelDrag()
      return
    }

    if (isLifted) {
      switch (event.key) {
        case "ArrowUp":
          event.preventDefault()
          board.moveLift("up")
          return
        case "ArrowDown":
          event.preventDefault()
          board.moveLift("down")
          return
        case "ArrowLeft":
          event.preventDefault()
          board.moveLift("left")
          return
        case "ArrowRight":
          event.preventDefault()
          board.moveLift("right")
          return
        case "Escape":
          event.preventDefault()
          board.cancelDrag()
          return
      }
    }
  }

  return (
    // Consumer props spread first so the attributes the card owns
    // (slot, drag transform, gesture handlers) always win.
    <div
      {...props}
      ref={composedRef}
      role="listitem"
      tabIndex={0}
      data-slot="kanban-card"
      data-card-id={cardId}
      data-dragging={isPointerDragging ? "true" : undefined}
      data-lifted={isLifted ? "true" : undefined}
      data-disabled={disabled || board.readOnly ? "true" : undefined}
      className={cn(
        // touch-none keeps the browser from claiming touch drags for
        // scrolling; column areas outside cards still scroll by touch.
        "box-border cursor-grab touch-none select-none data-[disabled=true]:cursor-default",
        // A dragged card leaves the flow entirely — its old slot closes and
        // the cards below rise — and floats above every column, clear of
        // any scrollable list that would otherwise clip it.
        "data-[dragging=true]:fixed data-[dragging=true]:z-50 data-[dragging=true]:cursor-grabbing data-[dragging=true]:shadow-xl",
        // A keyboard lift leaves the flow exactly as a pointer drag does,
        // so the column measures the same either way and the slot preview
        // lands where the card will actually go.
        "data-[lifted=true]:fixed data-[lifted=true]:z-50 data-[lifted=true]:shadow-xl",
        // Cards slide aside to open the slot. The card under the pointer
        // is placed every frame and opts out below, so it never lags.
        "transition-transform [transition-duration:var(--nessa-kanban-motion-duration,var(--nessa-motion-duration-fast))] [transition-timing-function:var(--nessa-motion-easing-standard)] motion-reduce:transition-none",
        "focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring",
        className,
      )}
      style={{
        ...style,
        ...(isPointerDragging || isLifted
          ? {
              // A transformed/filtered ancestor becomes the containing
              // block for position: fixed; its offset is subtracted so
              // the float lands where the card visually sat.
              left: dragState.origin.left - dragState.fixedOffset.x,
              top: dragState.origin.top - dragState.fixedOffset.y,
              width: dragState.origin.width,
              height: dragState.origin.height,
            }
          : null),
        // The floating card tracks the pointer directly; easing it would
        // make it swim behind the cursor — and net-zero poses (pickup,
        // settle) must not ease either, or the board visibly wobbles.
        // Only the kit's own duration is zeroed: `transition: none` would
        // also kill whatever the consumer styles on their card, and an
        // idle board is in exactly this state the whole time.
        ...(isPointerDragging || shiftIsInstant
          ? ({ "--nessa-kanban-motion-duration": "0s" } as React.CSSProperties)
          : null),
        // The float and the slide compose with (never replace) any
        // transform the consumer styles on, such as a tilt or hover scale.
        transform:
          [
            isPointerDragging
              ? `translate3d(${dragState.deltaX}px, ${dragState.deltaY}px, 0)`
              : null,
            shift > 0 ? `translate3d(0, ${shift}px, 0)` : null,
            typeof style?.transform === "string" ? style.transform : null,
          ]
            .filter(Boolean)
            .join(" ") || undefined,
      }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={(event) => {
        onPointerUp?.(event)
        handlePointerEnd(event, false)
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)
        handlePointerEnd(event, true)
      }}
      onKeyDown={handleKeyDown}
      onClick={(event) => {
        // The click that ends a drag is part of the drag, not an activation.
        if (suppressClickRef.current) {
          suppressClickRef.current = false
          event.preventDefault()
          event.stopPropagation()
          return
        }

        onClick?.(event)
      }}
      onBlur={(event) => {
        onBlur?.(event)

        // A lifted card whose focus walks away settles back where it was.
        if (isLifted) {
          board.cancelDrag()
        }
      }}
    />
  )
}

export { KanbanCard, type KanbanCardProps }

"use client"

/** @responsibility Coordinates the kanban board's shared state: the in-flight drag with targeted subscriptions, column and card registration, and the actions columns and cards use to talk to their board. */

import * as React from "react"

/** Where an in-flight drag would currently drop. */
interface KanbanDropTarget {
  /** The column the card would land in. */
  columnId: string
  /** The insertion index, counted with the dragged card removed. */
  index: number
  /** The opened slot's top, in the column list's content coordinates. */
  gapTop: number
  /** The opened slot's height: the moved card plus the column's spacing. */
  gapHeight: number
  /** The column's measured gap between cards, in pixels. */
  spacing: number
  /** The cards that shift down to open the slot. */
  shiftedCardIds: ReadonlySet<string>
}

/** The in-flight state of one card being moved, by pointer or keyboard. */
interface KanbanDragState {
  /** The card being moved. */
  cardId: string
  /** The column the card started in. */
  fromColumn: string
  /** The card's index in its column when the move started. */
  fromIndex: number
  /** Whether a pointer drag or a keyboard lift is moving the card. */
  mode: "pointer" | "keyboard"
  /** How far the pointer has travelled, in client pixels (pointer mode). */
  deltaX: number
  deltaY: number
  /**
   * Where the card sat when the drag began, in client pixels — the anchor
   * the floating card is positioned from (pointer mode).
   */
  origin: { left: number; top: number; width: number; height: number }
  /**
   * The fixed-position containing block's viewport offset (zero in a
   * plain document). Rendering subtracts it; hit-testing, which works in
   * viewport coordinates, uses `origin` as-is.
   */
  fixedOffset: { x: number; y: number }
  /** Where the card would drop right now, or null over no column. */
  over: KanbanDropTarget | null
}

/**
 * A single-value subscription store for the in-flight drag, so only the
 * dragged card and the hovered column's indicator re-render while it moves.
 */
interface KanbanDragStore {
  /** Reads the drag state; stable by reference until it changes. */
  get: () => KanbanDragState | null
  /** Replaces the drag state. */
  set: (state: KanbanDragState | null) => void
  /** Subscribes to drag-state changes; returns the disposer. */
  subscribe: (listener: () => void) => () => void
}

/**
 * Builds the drag store backing one board.
 *
 * @returns A fresh store with no drag in flight.
 */
function createKanbanDragStore(): KanbanDragStore {
  let state: KanbanDragState | null = null
  const listeners = new Set<() => void>()

  return {
    get: () => state,
    set: (next) => {
      if (next === state) {
        return
      }

      state = next

      for (const listener of listeners) listener()
    },
    subscribe: (listener) => {
      listeners.add(listener)

      return () => {
        listeners.delete(listener)
      }
    },
  }
}

/** Where an in-flight column drag would currently drop. */
interface KanbanColumnDropTarget {
  /** The column's destination index among its siblings. */
  index: number
  /** The opened slot's left edge, in the board's own coordinates. */
  gapLeft: number
  /** The opened slot's width: the moved column plus the board's spacing. */
  gapWidth: number
  /** The board's measured gap between columns, in pixels. */
  spacing: number
  /** How far, and which way, the parted columns slide. */
  shift: number
  /** The columns that shift to open the slot. */
  shiftedColumnIds: ReadonlySet<string>
}

/** The in-flight state of one column being moved. */
interface KanbanColumnDragState {
  /** The column being moved. */
  columnId: string
  /** The column's index when the move started. */
  fromIndex: number
  /** Whether a pointer drag or a keyboard lift is moving the column. */
  mode: "pointer" | "keyboard"
  /** How far the pointer has travelled, in client pixels (pointer mode). */
  deltaX: number
  /**
   * Vertical travel of the float. Always 0 when the board rails column
   * drags to the row; the destination is decided by X alone either way.
   */
  deltaY: number
  /** Where the column sat when the drag began, in client pixels. */
  origin: { left: number; top: number; width: number; height: number }
  /** The fixed-position containing block's viewport offset. */
  fixedOffset: { x: number; y: number }
  /** Where the column would drop right now. */
  over: KanbanColumnDropTarget | null
}

/** A settled column move reported to the board consumer. */
interface KanbanColumnMove {
  /** The column that moved. */
  columnId: string
  /**
   * The column's destination position, counted with the moved column
   * already removed from its original position.
   */
  index: number
}

/** A single-value subscription store for the in-flight column drag. */
interface KanbanColumnDragStore {
  get: () => KanbanColumnDragState | null
  set: (state: KanbanColumnDragState | null) => void
  subscribe: (listener: () => void) => () => void
}

/**
 * Builds the column-drag store backing one board.
 *
 * @returns A fresh store with no column drag in flight.
 */
function createKanbanColumnDragStore(): KanbanColumnDragStore {
  let state: KanbanColumnDragState | null = null
  const listeners = new Set<() => void>()

  return {
    get: () => state,
    set: (next) => {
      if (next === state) {
        return
      }

      state = next

      for (const listener of listeners) listener()
    },
    subscribe: (listener) => {
      listeners.add(listener)

      return () => {
        listeners.delete(listener)
      }
    },
  }
}

/** Shared state and actions provided by one KanbanBoard. */
interface KanbanContextValue {
  /**
   * Whether the board is a read-only view: nothing can be picked up, by
   * pointer or keyboard, and no move is ever reported.
   */
  readOnly: boolean
  /** The in-flight card drag. */
  drag: KanbanDragStore
  /** The in-flight column drag. */
  columnDrag: KanbanColumnDragStore
  /** Registers a column's outer element; returns the disposer. */
  registerColumnRoot: (columnId: string, element: HTMLElement) => () => void
  /** Starts a pointer drag of a whole column. */
  beginColumnDrag: (
    columnId: string,
    clientX: number,
    origin: { left: number; top: number; width: number; height: number },
  ) => boolean
  /** Continues the column drag this column owns. */
  moveColumnDrag: (
    columnId: string,
    startClientX: number,
    startClientY: number,
    clientX: number,
    clientY: number,
  ) => void
  /** Settles the column drag this column owns. */
  endColumnDrag: (columnId: string) => void
  /** Lifts a column for keyboard movement. */
  liftColumn: (columnId: string) => void
  /** Moves a keyboard-lifted column one step. */
  moveColumnLift: (direction: "left" | "right") => void
  /** Drops a keyboard-lifted column at its current target. */
  dropColumnLift: () => void
  /** Abandons the in-flight column drag or lift. */
  cancelColumnDrag: () => void
  /**
   * Registers a column's card-list element and whether it accepts drops;
   * returns the disposer.
   */
  registerColumn: (
    columnId: string,
    element: HTMLElement,
    accepts: boolean,
  ) => () => void
  /** Registers a card element in a column; returns the disposer. */
  registerCard: (
    cardId: string,
    columnId: string,
    element: HTMLElement,
  ) => () => void
  /**
   * Starts a pointer drag once the pointer commits to moving. Returns
   * false — and starts nothing — while another gesture already owns the
   * board, so a second pointer can disarm itself.
   */
  beginPointerDrag: (
    cardId: string,
    columnId: string,
    clientX: number,
    clientY: number,
    origin: { left: number; top: number; width: number; height: number },
  ) => boolean
  /** Continues the pointer drag this card owns at a client point. */
  movePointerDrag: (
    cardId: string,
    startClientX: number,
    startClientY: number,
    clientX: number,
    clientY: number,
  ) => void
  /**
   * Settles the pointer drag this card owns: commits over a column,
   * cancels elsewhere.
   */
  endPointerDrag: (cardId: string) => void
  /** Lifts a card for keyboard movement. */
  liftCard: (cardId: string, columnId: string) => void
  /** Moves a keyboard-lifted card one step. */
  moveLift: (direction: "up" | "down" | "left" | "right") => void
  /** Drops a keyboard-lifted card at its current target. */
  dropLift: () => void
  /** Abandons the in-flight drag or lift. */
  cancelDrag: () => void
}

const KanbanContext = React.createContext<KanbanContextValue | null>(null)

/** The column a card or list part belongs to. */
interface KanbanColumnContextValue {
  /** The owning column's id. */
  columnId: string
}

const KanbanColumnContext =
  React.createContext<KanbanColumnContextValue | null>(null)

/**
 * Reads the coordination state of the nearest KanbanBoard.
 *
 * @param consumer - The component name reported when used outside a board.
 * @returns The current board context value.
 * @throws When called outside a KanbanBoard.
 */
function useKanban(consumer: string): KanbanContextValue {
  const context = React.useContext(KanbanContext)

  if (context === null) {
    throw new Error(`${consumer} must be used within a KanbanBoard.`)
  }

  return context
}

/**
 * Subscribes to the in-flight card drag, re-rendering the caller only
 * while a drag is active.
 *
 * @returns The drag state, or null when no card is being moved.
 */
function useKanbanDragState(): KanbanDragState | null {
  const { drag } = useKanban("useKanbanDragState")

  return React.useSyncExternalStore(drag.subscribe, drag.get, () => null)
}

/**
 * Subscribes to the in-flight column drag, re-rendering the caller only
 * while a column is being moved.
 *
 * @returns The column drag state, or null when no column is being moved.
 */
function useKanbanColumnDragState(): KanbanColumnDragState | null {
  const { columnDrag } = useKanban("useKanbanColumnDragState")

  return React.useSyncExternalStore(
    columnDrag.subscribe,
    columnDrag.get,
    () => null,
  )
}

/**
 * Finds the offset of the coordinate space `position: fixed` will actually
 * use for an element. An ancestor with a transform, filter, perspective,
 * or paint containment becomes the fixed-position containing block, so
 * viewport coordinates must be shifted by its origin or the float lands
 * in the wrong place. (A scaling ancestor also scales the space — that
 * remains a documented limitation, as it is for every fixed-overlay drag.)
 *
 * @param element - The element about to become fixed.
 * @returns The containing block's viewport offset, or zero when the
 * viewport itself is the containing block.
 */
function kanbanFixedOffset(element: HTMLElement): { x: number; y: number } {
  let ancestor = element.parentElement

  while (ancestor) {
    const style = getComputedStyle(ancestor)

    // The individual transform properties (translate/rotate/scale) and
    // layout containment establish fixed-position containing blocks while
    // leaving computed `transform`/`contain` untouched — Tailwind v4's
    // translate-*/rotate-*/scale-* utilities emit exactly these longhands,
    // so they are as reachable as `transform` itself.
    const longhandTransform = (value: string | undefined) =>
      value !== undefined && value !== "" && value !== "none"

    if (
      style.transform !== "none" ||
      longhandTransform(style.translate) ||
      longhandTransform(style.rotate) ||
      longhandTransform(style.scale) ||
      style.filter !== "none" ||
      style.backdropFilter !== "none" ||
      style.perspective !== "none" ||
      style.willChange.includes("transform") ||
      style.willChange.includes("translate") ||
      style.willChange.includes("rotate") ||
      style.willChange.includes("scale") ||
      style.willChange.includes("filter") ||
      style.willChange.includes("perspective") ||
      /layout|paint|content|strict/.test(style.contain) ||
      (style.contentVisibility !== undefined &&
        style.contentVisibility !== "" &&
        style.contentVisibility !== "visible")
    ) {
      const rect = ancestor.getBoundingClientRect()

      return {
        x: rect.left + ancestor.clientLeft,
        y: rect.top + ancestor.clientTop,
      }
    }

    ancestor = ancestor.parentElement
  }

  return { x: 0, y: 0 }
}

/**
 * Builds one ref callback that feeds an element to our internal ref and to
 * a ref the consumer may have passed, so neither side loses it.
 *
 * @param internal - The component's own element ref.
 * @param forwarded - The consumer's ref, if any.
 * @returns A ref callback serving both.
 */
function composeKanbanRefs<Element>(
  internal: React.RefObject<Element | null>,
  forwarded: React.Ref<Element> | undefined,
): React.RefCallback<Element> {
  return (element) => {
    internal.current = element

    if (typeof forwarded === "function") {
      const cleanup = forwarded(element)

      // A consumer ref returning a cleanup (React 19) never receives a
      // null call, so the composed ref honours the same contract.
      if (typeof cleanup === "function") {
        return () => {
          internal.current = null
          cleanup()
        }
      }
    } else if (forwarded) {
      forwarded.current = element
    }
  }
}

